function kthSmallestGap(nums: number[], k: number): number {
  const gaps: number[] = [];
  for (let i = 0; i < nums.length; i++)
    for (let j = i + 1; j < nums.length; j++) gaps.push(Math.abs(nums[i] - nums[j]));
  gaps.sort((a, b) => a - b);
  return gaps[k - 1];
}

