function kthSmallestGap(nums: number[], k: number): number {
  const a = nums.slice().sort((x, y) => x - y);
  const n = a.length;
  const atMost = (d: number): number => {
    let count = 0, i = 0;
    for (let j = 1; j < n; j++) {
      while (a[j] - a[i] > d) i++;
      count += j - i;
    }
    return count;
  };
  let lo = 0, hi = a[n - 1] - a[0];
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (atMost(mid) >= k) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

