class Solution:
    def kthSmallestGap(self, nums: List[int], k: int) -> int:
        a = sorted(nums)
        n = len(a)

        def at_most(d):
            count = i = 0
            for j in range(1, n):
                while a[j] - a[i] > d:
                    i += 1
                count += j - i
            return count

        lo, hi = 0, a[-1] - a[0]
        while lo < hi:
            mid = (lo + hi) // 2
            if at_most(mid) >= k:
                hi = mid
            else:
                lo = mid + 1
        return lo

